package main

import (
	"flag"
	"fmt"
	"os"
	"strings"

	"github.com/mvanhorn/printing-press-library/library/productivity/bonusly/internal/cli"
	mcptools "github.com/mvanhorn/printing-press-library/library/productivity/bonusly/internal/mcp"
	"github.com/mark3labs/mcp-go/server"
)

// Transport selection order: --transport flag, then PP_MCP_TRANSPORT env,
// then the first transport declared in the spec (see MCPConfig.Transport).
// The flag surface lets one binary serve stdio locally and streamable HTTP
// when hosted in a container or remote sandbox, matching the Anthropic
// guidance that production agents need a remote option.

// pp:hand-edit bonusly-mcp-loopback-only — was ":7777", which Go's
// http.ListenAndServe binds to all interfaces (0.0.0.0). The registered MCP
// tools include credential-backed recognition mutations (create/update/
// delete) with no caller-authentication middleware, so an all-interface
// bind would let any network peer reachable on this port invoke them using
// the host user's stored Bonusly credentials. Default to loopback-only;
// --addr still allows an explicit, informed opt-in to a wider bind for
// operators who have their own network-level access control.
const (
	defaultHTTPAddr = "127.0.0.1:7777"
)

// version is the printed MCP server's version, overridable at build time via ldflags.
var version = "0.0.0-dev"

func main() {
	// Pin the learn-event surface for this process and every walker
	// shell-out child, so usage events record surface=mcp.
	_ = os.Setenv("BONUSLY_LEARN_SURFACE", "mcp")
	if err := cli.BindMCPServerProfile(); err != nil {
		fmt.Fprintf(os.Stderr, "MCP client-profile bind failed: %v\n", err)
		os.Exit(1)
	}
	s := server.NewMCPServer(
		"Bonusly",
		version,
		server.WithToolCapabilities(false),
	)

	mcptools.RegisterTools(s)

	transport := flag.String("transport", defaultTransport(), "MCP transport: stdio | http")
	// pp:hand-edit bonusly-mcp-loopback-only — flag help updated to carry
	// the security tradeoff forward for anyone who overrides the default.
	addr := flag.String("addr", defaultHTTPAddr, "bind address for http transport (host:port or :port). Default is loopback-only; registered tools include credential-backed recognition mutations with no caller authentication, so binding to a non-loopback address exposes them to any peer that can reach this port.")
	flag.Parse()

	switch strings.ToLower(*transport) {
	case "stdio":
		if err := server.ServeStdio(s); err != nil {
			fmt.Fprintf(os.Stderr, "MCP server error: %v\n", err)
			os.Exit(1)
		}
	case "http":
		httpSrv := server.NewStreamableHTTPServer(s)
		fmt.Fprintf(os.Stderr, "bonusly-pp-mcp serving MCP over streamable HTTP at %s\n", *addr)
		if err := httpSrv.Start(*addr); err != nil {
			fmt.Fprintf(os.Stderr, "MCP server error: %v\n", err)
			os.Exit(1)
		}
	default:
		fmt.Fprintf(os.Stderr, "unknown --transport %q (supported: stdio, http)\n", *transport)
		os.Exit(2)
	}
}

// defaultTransport reads PP_MCP_TRANSPORT env when set, otherwise falls back
// to "stdio" so running the binary with no args keeps today's behavior.
// Container-hosted agents can pin the transport via env without a flag, which
// matches how hosted-agent process supervisors typically pass configuration.
func defaultTransport() string {
	if t := os.Getenv("PP_MCP_TRANSPORT"); t != "" {
		return t
	}
	return "stdio"
}
